import app from '@/store/app';
import { MenuItem } from '@/types/menu';
import { IRoute } from "@/types/route"
import { convertToTree } from "@/utils"
import ajax from "@/utils/ajax"

/**
 * 获取菜单列表
 */
export const getMenuList = async (params: any): Promise<MenuItem[]> => {
    let menus = await ajax.post('/apijson/get', {
        "Menu[]": {
            "count": 0,
            "Menu": {
                ...params,
                '@order': 'sort+',
                "@column": ['id', 'type', 'authority', 'icon', 'isActive', 'name', 'pageId', 'path', 'parentId', 'isShow'].join(',')
            },
        }
    }).then((res) => {
        return res.Menu;
    })
    return menus;
}







/**
 * 获取页面数据详情
 */
export const getPageData =async (pageId: string) => {
    return ajax.post('/apijson/get', {
        Page: {
            id: pageId
        }
    }).then((res) => {
        const page = { ...res.Page };
        const { content, extraInfo } = res.Page;
        if(content){
            page.content = JSON.parse(content);
        }
        if(extraInfo){
            page.extraInfo = JSON.parse(extraInfo);
        }
        return page;
    })
}


/**
 * 发布App全局文件
 */
export const postPublishApp = async (appId: string) => {
    return ajax.post("/publishApp", {
        appId: appId || "app"
    })
}